const body = $json.body || $json;

const sql = (value) => {
  if (value === undefined || value === null || String(value).trim() === '') return 'NULL';
  return `'${String(value).replace(/'/g, "''")}'`;
};

const avatar = String(body.avatar || '').trim();
const scene = String(body.scene || '').trim();
const format = String(body.format || '').trim();
const objective = String(body.objective || '').trim();
const businessProfile = 'influencer-brand';
const assetType = 'raw-image';
const status = 'draft';
const allowedFormats = new Set(['feed-post', 'story', 'reel', 'carousel']);
const slugRegex = /^[a-z0-9][a-z0-9-]*$/i;
const errors = [];

if (!slugRegex.test(avatar)) errors.push('avatar is required and must be a slug');
if (!slugRegex.test(scene)) errors.push('scene is required and must be a slug');
if (!allowedFormats.has(format)) errors.push('format must be feed-post, story, reel, or carousel');
if (!objective) errors.push('objective is required');

let query;
if (errors.length > 0) {
  query = `SELECT false AS ok, ${sql(errors.join('; '))} AS error;`;
} else {
  query = [
    'CREATE EXTENSION IF NOT EXISTS pgcrypto;',
    `CREATE TABLE IF NOT EXISTS publication_jobs (
      publication_job_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      avatar TEXT NOT NULL,
      scene TEXT NOT NULL,
      format TEXT NOT NULL,
      objective TEXT NOT NULL,
      business_profile TEXT NOT NULL DEFAULT 'influencer-brand',
      asset_type TEXT NOT NULL DEFAULT 'raw-image',
      status TEXT NOT NULL DEFAULT 'draft',
      brief JSONB NULL,
      prompt_pack JSONB NULL,
      selected_asset_id UUID NULL,
      publishing_pack JSONB NULL,
      published_platform TEXT NULL,
      published_url TEXT NULL,
      published_at TIMESTAMPTZ NULL,
      error_message TEXT NULL,
      metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
      created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
    );`,
    'CREATE INDEX IF NOT EXISTS publication_jobs_avatar_scene_idx ON publication_jobs (avatar, scene);',
    'CREATE INDEX IF NOT EXISTS publication_jobs_status_created_idx ON publication_jobs (status, created_at DESC);',
    `INSERT INTO publication_jobs (
      avatar,
      scene,
      format,
      objective,
      business_profile,
      asset_type,
      status,
      metadata
    ) VALUES (
      ${sql(avatar)},
      ${sql(scene)},
      ${sql(format)},
      ${sql(objective)},
      ${sql(businessProfile)},
      ${sql(assetType)},
      ${sql(status)},
      jsonb_build_object('source', 'asset-review-dashboard', 'version', 1)
    )
    RETURNING
      true AS ok,
      publication_job_id AS "publicationJobId",
      avatar,
      scene,
      format,
      objective,
      business_profile AS "businessProfile",
      asset_type AS "assetType",
      status,
      created_at AS "createdAt",
      updated_at AS "updatedAt";`
  ].join('\n');
}

return [{ json: { query } }];

const row = $input.first()?.json || {};

if (row.ok === false || row.ok === 'f') {
  return [{
    json: {
      ok: false,
      error: row.error || 'Publication job was not created.'
    }
  }];
}

return [{
  json: {
    ok: true,
    job: {
      publicationJobId: row.publicationJobId,
      avatar: row.avatar,
      scene: row.scene,
      format: row.format,
      objective: row.objective,
      businessProfile: row.businessProfile,
      assetType: row.assetType,
      status: row.status,
      createdAt: row.createdAt,
      updatedAt: row.updatedAt
    }
  }
}];
